import { useEffect, useMemo, useState } from 'react';
import { Link, NavLink, Route, Routes, useLocation, useNavigate, useParams } from 'react-router-dom';
import { Activity, ArrowDown, ArrowLeft, ArrowRight, Bell, CalendarDays, Check, ChevronDown, ChevronRight, CircleHelp, CloudSun, Droplets, Gauge, Globe2, Heart, Home, Leaf, MapPin, Menu, MessageCircle, Plus, Search, Settings, ShieldCheck, Sprout, TrendingDown, TrendingUp, Users, X } from 'lucide-react';
import { CartesianGrid, Line, LineChart, ResponsiveContainer, Tooltip, XAxis, YAxis, Bar, BarChart } from 'recharts';
import { crops, type Crop } from './data/crops';
import { t } from './i18n/translations';

type Lang = 'mr' | 'hi' | 'en';

const navItems = [
 {label:'home',to:'/farmer/dashboard',icon:Home,group:'Farm'}, {label:'profile',to:'/farmer/farm-profile',icon:Sprout,group:'Farm'}, {label:'advisory',to:'/farmer/advisory/setup',icon:Leaf,group:'Plan'}, {label:'calendar',to:'/farmer/sowing-calendar',icon:CalendarDays,group:'Plan'}, {label:'mandi',to:'/farmer/mandi',icon:TrendingUp,group:'Plan'}, {label:'weather',to:'/farmer/weather',icon:CloudSun,group:'Plan'}, {label:'expert',to:'/farmer/expert',icon:MessageCircle,group:'Support'}, {label:'history',to:'/farmer/history',icon:Activity,group:'Support'}, {label:'settings',to:'/farmer/settings',icon:Settings,group:'Support'}
];
const fmt=(n:number)=>new Intl.NumberFormat('en-IN',{maximumFractionDigits:0}).format(n);
const getStore=<T,>(key:string, fallback:T):T=>{try {const v=localStorage.getItem(key); return v?JSON.parse(v):fallback;} catch{return fallback;}};
function App(){
 const [lang,setLang]=useState<Lang>(()=>getStore('pn-lang','mr')); const [profile,setProfile]=useState(()=>getStore('pn-profile',{district:'Pune',taluka:'Baramati',village:'Demo village',area:2,unit:'acres',soil:'Medium black',water:'Rainfed',previous:'Soybean',ph:7}));
 const [season,setSeason]=useState(()=>getStore('pn-season','Kharif')); const [risk,setRisk]=useState(()=>getStore('pn-risk','Balanced')); const [selected,setSelected]=useState<string[]>(()=>getStore('pn-selected',['soybean','tur'])); const [cases,setCases]=useState(()=>getStore<any[]>('pn-cases',[{id:'PN-1042',category:'Crop choice',message:'Should I grow soybean or tur this year?',status:'Answered',date:'18 Jun',answer:'Based on the sample profile, both are options to discuss with your local agriculture officer.'},{id:'PN-1038',category:'Soil & water',message:'How much water does chana need?',status:'In review',date:'16 Jun'}]));
 const [advisories,setAdvisories]=useState(()=>getStore<string[]>('pn-advisories',['soybean','chana']));
 useEffect(()=>{localStorage.setItem('pn-lang',JSON.stringify(lang));document.documentElement.lang=lang;},[lang]); useEffect(()=>localStorage.setItem('pn-profile',JSON.stringify(profile)),[profile]); useEffect(()=>localStorage.setItem('pn-season',JSON.stringify(season)),[season]);useEffect(()=>localStorage.setItem('pn-risk',JSON.stringify(risk)),[risk]);useEffect(()=>localStorage.setItem('pn-selected',JSON.stringify(selected)),[selected]);useEffect(()=>localStorage.setItem('pn-cases',JSON.stringify(cases)),[cases]);useEffect(()=>localStorage.setItem('pn-advisories',JSON.stringify(advisories)),[advisories]);
 const tr=t[lang]; const loc=useLocation(); const navigate=useNavigate();
 const [drawer,setDrawer]=useState(false);
 const layout=/^\/(farmer|expert|admin)/.test(loc.pathname);
 return <>{layout?<div className="app-shell"><aside className={`sidebar ${drawer?'show':''}`}><Link to="/farmer/dashboard" className="brand"><span className="brand-mark">🌱</span><span><b>PikNirnay</b><small>पीक निर्णय</small></span><button className="icon-btn mobile-close" onClick={()=>setDrawer(false)}><X size={18}/></button></Link><div className="season-chip"><span className="season-icon"><Sprout size={15}/></span><span><b>{season} 2026</b><small>Planning season</small></span><ChevronDown size={14}/></div><div className="nav-scroll">{['Farm','Plan','Support'].map(group=><div className="nav-group" key={group}><small className="nav-label">{group}</small>{navItems.filter(n=>n.group===group).map(n=><NavLink key={n.to} to={n.to} onClick={()=>setDrawer(false)} className={({isActive})=>`nav-link ${isActive?'active':''}`}><n.icon size={18}/><span>{tr[n.label as keyof typeof tr]}</span>{n.label==='expert'&&cases.filter(c=>c.status==='In review'||c.status==='Pending').length>0&&<i className="nav-dot"/>}</NavLink>)}</div>)}<div className="nav-group"><small className="nav-label">Workspace</small><NavLink to="/expert/dashboard" className={({isActive})=>`nav-link ${isActive?'active':''}`}><Users size={18}/><span>{tr.roleExpert}</span></NavLink><NavLink to="/admin/dashboard" className={({isActive})=>`nav-link ${isActive?'active':''}`}><Gauge size={18}/><span>{tr.roleAdmin}</span></NavLink></div></div><div className="sidebar-bottom"><div className="help-card"><div className="help-icon"><CircleHelp size={17}/></div><b>Need a hand?</b><p>Talk to a local agriculture expert.</p><Link to="/farmer/expert">Ask a question <ArrowRight size={13}/></Link></div><Link to="/farmer/settings" className="user-row"><div className="avatar">शे</div><span><b>Demo Farmer</b><small>{profile.village}, {profile.district}</small></span><ChevronDown size={15}/></Link></div></aside><div className="main-column"><header className="topbar"><button className="icon-btn menu-btn" onClick={()=>setDrawer(true)}><Menu size={20}/></button><div className="crumb"><span>My farm</span><ChevronRight size={14}/><b>{titleFor(loc.pathname,tr)}</b></div><div className="top-actions"><div className="demo-pill"><span/> DEMO MODE</div><select className="lang-select" aria-label="Language" value={lang} onChange={e=>setLang(e.target.value as Lang)}><option value="mr">मराठी</option><option value="hi">हिंदी</option><option value="en">English</option></select><button className="icon-btn notification" title="Notifications"><Bell size={18}/><i/></button><div className="top-avatar">शे</div></div></header><main className="content"><Routes><Route path="/" element={<NavigateTo to="/"/>}/><Route path="/farmer/dashboard" element={<Dashboard tr={tr} profile={profile} crops={crops} season={season} navigate={navigate} advisories={advisories}/>}/><Route path="/farmer/farm-profile" element={<FarmProfile profile={profile} setProfile={setProfile} tr={tr}/>}/><Route path="/farmer/advisory/setup" element={<Setup tr={tr} season={season} setSeason={setSeason} risk={risk} setRisk={setRisk} onContinue={()=>{setAdvisories(prev=>[crops.find(c=>c.season===season)?.id||'soybean',...prev].slice(0,8));navigate('/farmer/advisory/results')}}/>}/><Route path="/farmer/advisory/results" element={<Results tr={tr} season={season} risk={risk} selected={selected} setSelected={setSelected}/>}/><Route path="/farmer/advisory/compare" element={<Compare tr={tr} selected={selected} setSelected={setSelected} season={season}/>}/><Route path="/farmer/advisory/why/:cropId" element={<Why tr={tr} season={season}/>}/><Route path="/farmer/sowing-calendar" element={<Calendar tr={tr} season={season}/>}/><Route path="/farmer/mandi" element={<Mandi tr={tr} season={season}/>}/><Route path="/farmer/weather" element={<Weather tr={tr}/>}/><Route path="/farmer/expert" element={<Expert tr={tr} cases={cases} setCases={setCases}/>}/><Route path="/farmer/history" element={<History tr={tr} advisories={advisories} navigate={navigate}/>}/><Route path="/farmer/settings" element={<SettingsPage tr={tr} lang={lang} setLang={setLang} profile={profile}/>}/><Route path="/expert/*" element={<ExpertDesk tr={tr} cases={cases} setCases={setCases}/>}/><Route path="/admin/*" element={<Admin tr={tr} cases={cases}/>}/><Route path="*" element={<NavigateTo to="/farmer/dashboard"/>}/></Routes><footer className="footer"><span>© 2026 PikNirnay</span><span>Made for Maharashtra <span className="heart">♥</span></span><Link to="/how-it-works">How this works</Link></footer></main></div></div>:<Routes><Route path="/" element={<Landing lang={lang} setLang={setLang}/>}/><Route path="/how-it-works" element={<PublicPage title="How it works" lang={lang} setLang={setLang}/>}/><Route path="/language" element={<LanguagePage lang={lang} setLang={setLang}/>}/><Route path="/welcome" element={<Welcome lang={lang} setLang={setLang}/>}/><Route path="/demo-access" element={<NavigateTo to="/farmer/dashboard"/>}/><Route path="*" element={<NavigateTo to="/"/>}/></Routes>}</>;
}
function titleFor(path:string,tr:any){const n=navItems.find(x=>x.to===path);if(n)return tr[n.label];if(path.includes('/advisory/setup'))return tr.advisory;if(path.includes('/advisory/results'))return 'Your recommendations';if(path.includes('/advisory/compare'))return tr.compare;if(path.includes('/advisory/why'))return 'Recommendation details';if(path.startsWith('/expert'))return tr.roleExpert;if(path.startsWith('/admin'))return tr.roleAdmin;return 'PikNirnay';}
function NavigateTo({to}:{to:string}){const n=useNavigate();useEffect(()=>n(to,{replace:true}),[n,to]);return null}
function Tag({children,tone='green'}:{children:any;tone?:string}){return <span className={`tag ${tone}`}>{children}</span>}
function DemoNote({tr}:any){return <div className="demo-note"><ShieldCheck size={15}/><span>{tr.demo}</span><button title="About this data"><CircleHelp size={15}/></button></div>}
function PageHead({eyebrow,title,subtitle,action}:any){return <div className="page-head"><div><span className="eyebrow">{eyebrow}</span><h1>{title}</h1>{subtitle&&<p>{subtitle}</p>}</div>{action}</div>}
function CropArt({crop,size='normal'}:{crop:Crop;size?:string}){return <div className={`crop-art ${size}`} style={{background:crop.tint}}><span>{crop.emoji}</span><i className="art-leaf">✳</i></div>}
function Dashboard({tr,profile,crops,season,navigate,advisories}:any){const list=crops.filter((c:Crop)=>c.season===season).slice(0,3);return <><div className="welcome-banner"><div className="welcome-copy"><div className="welcome-kicker"><span className="sun">☀</span> {tr.goodMorning}, Demo Farmer</div><h1>{tr.welcome}</h1><p>Let’s make this season’s crop choice with a little more clarity.</p><button className="btn btn-light" onClick={()=>navigate('/farmer/advisory/setup')}>{tr.start}<ArrowRight size={16}/></button></div><div className="banner-art"><div className="banner-sun"/><div className="hill hill-one"/><div className="hill hill-two"/><div className="field-lines"/><div className="crop-silhouette">🌾</div></div><div className="banner-tag"><span>✦</span> A better season starts here</div></div><DemoNote tr={tr}/><div className="section-title"><div><span className="eyebrow">YOUR FARM AT A GLANCE</span><h2>Season snapshot</h2></div><button className="text-link" onClick={()=>navigate('/farmer/farm-profile')}>{tr.edit}<ArrowRight size={14}/></button></div><div className="stat-grid"><div className="stat-card"><div className="stat-top"><span>{tr.area}</span><span className="stat-icon"><MapPin size={16}/></span></div><strong>{profile.area} <small>{profile.unit}</small></strong><p>{profile.village}, {profile.district}</p></div><div className="stat-card"><div className="stat-top"><span>{tr.soil}</span><span className="stat-icon warm"><Sprout size={16}/></span></div><strong className="stat-word">{profile.soil}</strong><p>{tr.season}: {season} 2026</p></div><div className="stat-card"><div className="stat-top"><span>{tr.water}</span><span className="stat-icon blue"><Droplets size={16}/></span></div><strong className="stat-word">{profile.water}</strong><p>Plan crops to match your water</p></div><div className="stat-card"><div className="stat-top"><span>Rainfall outlook</span><span className="stat-icon blue"><CloudSun size={16}/></span></div><strong>On track <small>for now</small></strong><p>Illustrative seasonal outlook</p></div></div><div className="section-title spaced"><div><span className="eyebrow">A GOOD PLACE TO START</span><h2>{tr.latest}</h2></div><button className="text-link" onClick={()=>navigate('/farmer/history')}>{tr.viewAll}<ArrowRight size={14}/></button></div><div className="crop-row">{list.map((c:Crop,i:number)=><div className="mini-crop-card" key={c.id}><CropArt crop={c}/><div className="mini-crop-content"><div className="mini-title"><b>{c.local}</b><Tag tone={i===0?'green':'amber'}>{i===0?tr.best:`${c.fit}% match`}</Tag></div><span className="crop-en">{c.name} · {c.window}</span><div className="mini-stats"><span>₹{fmt(c.low)}–{fmt(c.high)}</span><span className="risk-dot">{c.loss}% loss risk</span></div><button className="card-link" onClick={()=>navigate(`/farmer/advisory/why/${c.id}`)}>{tr.why}<ArrowRight size={14}/></button></div></div>)}</div><div className="bottom-promos"><button className="promo-card" onClick={()=>navigate('/farmer/sowing-calendar')}><div className="promo-icon leaf-bg"><CalendarDays size={19}/></div><div><b>Plan your sowing week</b><p>See the recommended window for {season.toLowerCase()}.</p></div><ChevronRight size={17}/></button><button className="promo-card" onClick={()=>navigate('/farmer/expert')}><div className="promo-icon expert-bg"><MessageCircle size={19}/></div><div><b>Have a question?</b><p>Get help from the expert desk.</p></div><ChevronRight size={17}/></button></div></>}
function FarmProfile({profile,setProfile,tr}:any){const [form,setForm]=useState(profile);const [saved,setSaved]=useState(false);const areaAcres=form.unit==='guntha'?Number(form.area||0)/40:Number(form.area||0);return <><PageHead eyebrow="YOUR DETAILS" title={tr.profile} subtitle="A few farm details help us make the sample advice more relevant."/><DemoNote tr={tr}/><form className="panel profile-form" onSubmit={e=>{e.preventDefault();setProfile(form);setSaved(true);setTimeout(()=>setSaved(false),2500)}}><div className="panel-heading"><div><h2>About your farm</h2><p>These details stay on this device.</p></div><span className="step-count">01 <span>/ 01</span></span></div><div className="form-grid"><label>State<select value={form.state||'Maharashtra'} onChange={e=>setForm({...form,state:e.target.value})}><option>Maharashtra</option></select></label><label>{tr.district}<select value={form.district} onChange={e=>setForm({...form,district:e.target.value})}>{['Pune','Nashik','Ahmednagar','Solapur','Nagpur','Amravati','Latur','Kolhapur','Jalgaon','Other'].map(x=><option key={x}>{x}</option>)}</select></label><label>Taluka<input value={form.taluka} onChange={e=>setForm({...form,taluka:e.target.value})}/></label><label>Village<input value={form.village} onChange={e=>setForm({...form,village:e.target.value})}/></label><label>{tr.area}<div className="input-unit"><input type="number" min="0.1" step="0.1" value={form.area} onChange={e=>setForm({...form,area:Number(e.target.value)})} required/><select value={form.unit} onChange={e=>{const unit=e.target.value;const converted=unit==='guntha'?Number(form.area)*40:Number(form.area)/40;setForm({...form,unit,area:Math.round(converted*100)/100})}}><option>acres</option><option>guntha</option></select></div><small className="field-help">40 guntha = 1 acre {form.unit==='guntha'&&`· ${areaAcres.toFixed(2)} acres`}</small></label><label>{tr.soil}<select value={form.soil} onChange={e=>setForm({...form,soil:e.target.value})}>{['Medium black','Deep black','Shallow black','Red','Laterite','Sandy loam','Other'].map(x=><option key={x}>{x}</option>)}</select></label><label>{tr.water}<select value={form.water} onChange={e=>setForm({...form,water:e.target.value})}>{['Rainfed','Limited irrigation','Reliable irrigation','Well','Canal','Other'].map(x=><option key={x}>{x}</option>)}</select></label><label>Previous crop<select value={form.previous} onChange={e=>setForm({...form,previous:e.target.value})}>{['Soybean','Cotton','Tur','Chana','Wheat','Jowar','Other'].map(x=><option key={x}>{x}</option>)}</select></label><label>Soil pH <span className="optional">OPTIONAL</span><input type="number" min="0" max="14" step="0.1" value={form.ph||''} onChange={e=>setForm({...form,ph:e.target.value?Number(e.target.value):''})} placeholder="e.g. 7.0"/></label></div><div className="form-bottom"><span>🔒 Your farm details are stored only in your browser.</span><button className="btn btn-primary" type="submit"><Check size={16}/>{saved?'Saved':tr.save}</button></div></form></>}
function Setup({tr,season,setSeason,risk,setRisk,onContinue}:any){return <><PageHead eyebrow="STEP 1 OF 1" title="Let’s plan your season" subtitle="Choose a season and tell us how much risk feels comfortable."/><DemoNote tr={tr}/><div className="panel setup-panel"><div className="setup-step"><div className="step-bubble">01</div><div><h2>Which season are you planning for?</h2><p>We'll show crops for this season in Maharashtra.</p></div></div><div className="option-grid"><button className={`season-option ${season==='Kharif'?'chosen':''}`} onClick={()=>setSeason('Kharif')}><span className="option-emoji">🌧️</span><div><b>Kharif</b><small>Monsoon · June – October</small></div>{season==='Kharif'&&<span className="checkmark"><Check size={13}/></span>}</button><button className={`season-option ${season==='Rabi'?'chosen':''}`} onClick={()=>setSeason('Rabi')}><span className="option-emoji">❄️</span><div><b>Rabi</b><small>Winter · October – March</small></div>{season==='Rabi'&&<span className="checkmark"><Check size={13}/></span>}</button></div><div className="setup-divider"/><div className="setup-step"><div className="step-bubble">02</div><div><h2>How do you feel about risk?</h2><p>There is no right answer — choose what works for your family.</p></div></div><div className="risk-options">{[{name:'Cautious',desc:'Lower costs and steadier options',icon:'🛡️',tone:'sage'},{name:'Balanced',desc:'A mix of return and resilience',icon:'⚖️',tone:'blue'},{name:'Ambitious',desc:'Higher potential, more uncertainty',icon:'📈',tone:'peach'}].map(o=><button className={`risk-option ${risk===o.name?'chosen':''}`} key={o.name} onClick={()=>setRisk(o.name)}><span className={`risk-emoji ${o.tone}`}>{o.icon}</span><b>{o.name}</b><small>{o.desc}</small>{risk===o.name&&<span className="risk-check"><Check size={13}/></span>}</button>)}</div><div className="setup-footer"><div><b>Farm profile ready</b><span><Check size={13}/> 2 acres · Medium black soil · Rainfed</span></div><button className="btn btn-primary btn-large" onClick={onContinue}>{tr.continue}<ArrowRight size={17}/></button></div></div></>}
function Results({tr,season,risk,selected,setSelected}:any){const nav=useNavigate();const list=crops.filter(c=>c.season===season).slice(0,3);return <><PageHead eyebrow={`${season.toUpperCase()} SEASON · ${risk.toUpperCase()} PROFILE`} title="Your crop shortlist" subtitle="A few options worth exploring for your farm." action={<button className="btn btn-outline" onClick={()=>nav('/farmer/advisory/setup')}><ArrowLeft size={15}/>Change choices</button>}/><DemoNote tr={tr}/><div className="result-intro"><div className="result-icon"><Sparkle/></div><div><b>Three options, one clearer decision.</b><span>Ranked using your farm details, selected season and risk comfort.</span></div><Tag tone="green">Personalised demo</Tag></div><div className="results-list">{list.map((c,i)=><CropCard key={c.id} crop={c} rank={i} tr={tr} selected={selected} setSelected={setSelected}/>)}</div><div className="results-bottom"><div><b>Want to see the trade-offs?</b><span>Select two crops above, then compare their costs and risk.</span></div><button disabled={selected.length!==2} className="btn btn-primary" onClick={()=>nav('/farmer/advisory/compare')}>{tr.compare} ({selected.length}/2)<ArrowRight size={16}/></button></div></>}
function Sparkle(){return <span>✦</span>}
function CropCard({crop,rank,tr,selected,setSelected}:any){const nav=useNavigate();const checked=selected.includes(crop.id);const toggle=()=>setSelected((s:string[])=>checked?s.filter(x=>x!==crop.id):s.length<2?[...s,crop.id]:[s[1],crop.id]);return <article className={`result-card ${rank===0?'recommended':''}`}><div className="crop-image-wrap"><CropArt crop={crop} size="large"/>{rank===0&&<span className="best-ribbon">TOP MATCH</span>}<button className={`save-heart ${checked?'saved':''}`} title="Select for comparison" onClick={toggle}><Heart size={17} fill={checked?'currentColor':'none'}/></button></div><div className="result-main"><div className="crop-heading"><div><span className="crop-native">{crop.local}</span><h3>{crop.name}</h3></div><Tag tone={rank===0?'green':'neutral'}>{crop.fit}% fit</Tag></div><div className="crop-metrics"><div><small>{tr.cost}</small><b>₹{fmt(crop.cost)} <i>– ₹{fmt(crop.cost+6500)}</i></b></div><div><small>{tr.return}</small><b className="green-text">₹{fmt(crop.low)} <i>– ₹{fmt(crop.high)}</i></b></div><div><small>{tr.loss}</small><b>{crop.loss}<i>%</i><span className="risk-meter"><i style={{width:`${crop.loss*2.1}px`}}/></span></b></div></div><div className="result-footer"><span><CalendarDays size={14}/> Sow {crop.window}</span><span><ShieldCheck size={14}/> {crop.confidence} confidence</span><button className="card-link" onClick={()=>nav(`/farmer/advisory/why/${crop.id}`)}>{tr.why}<ArrowRight size={14}/></button></div></div></article>}
function Compare({tr,selected,setSelected,season}:any){const nav=useNavigate();const [a,b]=selected.map((id:string)=>crops.find(c=>c.id===id)||crops.find(c=>c.season===season)!);const pair=[a,b];return <><PageHead eyebrow="SIDE BY SIDE" title={tr.compare} subtitle="Look at the trade-offs before you decide." action={<button className="btn btn-outline" onClick={()=>nav('/farmer/advisory/results')}><ArrowLeft size={15}/>Back to advice</button>}/><DemoNote tr={tr}/><div className="compare-toolbar"><span>{tr.selectCrop} — choose up to two</span><div>{crops.filter(c=>c.season===season).map(c=><button key={c.id} className={`chip ${selected.includes(c.id)?'on':''}`} onClick={()=>setSelected((s:string[])=>s.includes(c.id)?s.filter(x=>x!==c.id):s.length<2?[...s,c.id]:[s[1],c.id])}>{c.local} {selected.includes(c.id)&&<Check size={12}/>}</button>)}</div></div><div className="compare-grid">{pair.map((c:Crop|undefined,i:number)=>c&&<div className="compare-card" key={c.id}><div className="compare-crop-art"><CropArt crop={c} size="large"/></div><div className="compare-crop-title"><span>{i===0?'OPTION 01':'OPTION 02'}</span><h2>{c.local}</h2><p>{c.name}</p><Tag tone="green">{c.fit}% suitable</Tag></div><Metric label="Estimated cost / acre" value={`₹${fmt(c.cost)} – ₹${fmt(c.cost+6500)}`}/><Metric label="Estimated net return / acre" value={`₹${fmt(c.low)} – ₹${fmt(c.high)}`} accent/><Metric label="Chance of loss" value={`${c.loss}%`} risk/><Metric label="Water requirement" value={c.water}/><Metric label="Crop duration" value={`${c.duration} days`}/><Metric label="Sowing period" value={c.window}/><button className="card-link full-link" onClick={()=>nav(`/farmer/advisory/why/${c.id}`)}>Understand this recommendation<ArrowRight size={14}/></button></div>)}</div>{pair.filter(Boolean).length<2&&<div className="empty-inline">Select one more crop to compare.</div>}</>}
function Metric({label,value,accent,risk}:any){return <div className="metric-row"><span>{label}</span><b className={accent?'green-text':risk?'amber-text':''}>{value}</b></div>}
function Why({tr,season}:any){const {cropId}=useParams();const crop=crops.find(c=>c.id===cropId)||crops[0];return <><PageHead eyebrow="THE REASONS BEHIND THE RESULT" title={tr.why} subtitle={`A closer look at the sample ${crop.name} recommendation.`} action={<Link className="btn btn-outline" to="/farmer/advisory/results"><ArrowLeft size={15}/>Back to shortlist</Link>}/><DemoNote tr={tr}/><div className="why-hero"><CropArt crop={crop} size="large"/><div><Tag tone="green">{crop.fit}% suitability · {crop.confidence} confidence</Tag><h2>{crop.local} <span>· {crop.name}</span></h2><p>Suggested for {season} based on the farm profile you shared.</p></div></div><div className="why-grid"><section className="panel reason-panel"><span className="eyebrow">WHY IT MAY FIT</span><h2>Three things went into this</h2>{crop.reasons.map((r,i)=><div className="reason-row" key={r}><span className="reason-number">0{i+1}</span><div><b>{['Soil match','Water fit','Season timing'][i]}</b><p>{r}</p></div><Check size={16} className="reason-check"/></div>)}<div className="confidence-box"><Gauge size={17}/><div><b>How to read the confidence</b><p>{crop.confidence} means the demonstration has only partial sample inputs for this profile. Local yields, prices and field conditions can change the outcome.</p></div></div></section><section className="panel detail-panel"><span className="eyebrow">PROFILE MATCH</span><h2>What we considered</h2><Metric label="Soil type" value="Medium black · suitable"/><Metric label="Water available" value="Rainfed · low water"/><Metric label="Season" value={`${season} · compatible`}/><Metric label="Sowing window" value={crop.window}/><Metric label="Data source" value="Illustrative sample"/><div className="info-callout"><CircleHelp size={16}/><span>This is not a verified field recommendation. Please confirm timing and crop choice with your local agriculture officer.</span></div></section></div><section className="panel what-if"><div><span className="eyebrow">WHAT IF?</span><h2>Explore a different situation</h2><p>These are hypothetical scenarios, not forecasts.</p></div><div className="scenario-row"><div className="scenario"><span className="scenario-icon">💧</span><div><b>If irrigation is available</b><p>Suitability could improve by about 5 points in this illustration.</p></div><span className="scenario-up">+5</span></div><div className="scenario"><span className="scenario-icon">🌧️</span><div><b>If rainfall is below normal</b><p>Estimated loss chance could rise in a dry spell scenario.</p></div><span className="scenario-down">+12%</span></div></div></section></>}
const weekData=[{day:'Mon',rain:10,temp:30},{day:'Tue',rain:5,temp:31},{day:'Wed',rain:22,temp:28},{day:'Thu',rain:18,temp:29},{day:'Fri',rain:0,temp:32},{day:'Sat',rain:12,temp:30},{day:'Sun',rain:8,temp:29}];
function Calendar({tr,season}:any){const weeks=season==='Kharif'?['Jun 1–7','Jun 8–14','Jun 15–21','Jun 22–28','Jun 29–Jul 5','Jul 6–12','Jul 13–19','Jul 20–26']:['Oct 13–19','Oct 20–26','Oct 27–Nov 2','Nov 3–9','Nov 10–16','Nov 17–23','Nov 24–30','Dec 1–7'];return <><PageHead eyebrow={`${season.toUpperCase()} PLANNING`} title={tr.calendar} subtitle="Timing is one of the most important decisions you can make."/><DemoNote tr={tr}/><section className="panel calendar-panel"><div className="calendar-head"><div><span className="eyebrow">SAMPLE SOWING WINDOW</span><h2>Soybean · {season} season</h2><p>Always check local rainfall and soil moisture before sowing.</p></div><Tag tone="amber">Illustrative timing</Tag></div><div className="window-legend"><span><i className="early"/> Earliest</span><span><i className="preferred"/> Preferred</span><span><i className="late"/> Latest suggested</span></div><div className="week-grid">{weeks.map((w,i)=><div key={w} className={`week ${i<2?'early-week':i<5?'preferred-week':'late-week'}`}><small>WEEK {i+1}</small><b>{w}</b>{i===3&&<span>Good window</span>}</div>)}</div><div className="calendar-foot"><span><CloudSun size={17}/> Wait for a steady monsoon onset, not just the first shower.</span><button className="text-link" onClick={()=>location.href='/farmer/weather'}>View weather outlook <ArrowRight size={14}/></button></div></section><section className="panel calendar-advice"><div className="advice-icon"><CalendarDays size={20}/></div><div><b>Keep an eye on the soil</b><p>Soil should have enough moisture through the top layer. Sample dates do not account for local rainfall variation.</p></div><Link to="/farmer/expert" className="text-link">Ask an expert <ArrowRight size={14}/></Link></section></>}
const priceData=[{m:'Jan',p:4620},{m:'Feb',p:4780},{m:'Mar',p:4510},{m:'Apr',p:4890},{m:'May',p:5120},{m:'Jun',p:4980},{m:'Jul',p:5340},{m:'Aug',p:5210},{m:'Sep',p:5600},{m:'Oct',p:5480},{m:'Nov',p:5810},{m:'Dec',p:5690}];
function Mandi({tr,season}:any){const [crop,setCrop]=useState('Soybean');const [market,setMarket]=useState('Pune');const [period,setPeriod]=useState('12 months');const active=priceData.slice(period==='6 months'?6:0);return <><PageHead eyebrow="MARKET SNAPSHOT" title={tr.mandi} subtitle="Demonstration market prices help you explore the view. They are not today's live rates."/><DemoNote tr={tr}/><div className="filter-bar"><label>Crop<select value={crop} onChange={e=>setCrop(e.target.value)}>{crops.filter(c=>c.season===season).map(c=><option key={c.id}>{c.name}</option>)}</select></label><label>Market<select value={market} onChange={e=>setMarket(e.target.value)}>{['Pune','Baramati','Nashik','Solapur','Ahmednagar'].map(x=><option key={x}>{x}</option>)}</select></label><div className="segmented">{['6 months','12 months'].map(p=><button key={p} className={period===p?'selected':''} onClick={()=>setPeriod(p)}>{p}</button>)}</div></div><div className="market-summary"><div><small>Modal price · today</small><b>₹5,420 <span>/ quintal</span></b><i className="positive"><TrendingUp size={14}/> 4.2% over sample prior month</i></div><div><small>Minimum – maximum</small><b>₹4,850 – ₹5,800</b><i>Illustrative range</i></div><div><small>Data status</small><b><Tag tone="amber">Sample values</Tag></b><i>Not an official mandi quote</i></div></div><section className="panel chart-panel"><div className="chart-heading"><div><span className="eyebrow">HISTORICAL TREND · ₹ / QUINTAL</span><h2>{crop} in {market}</h2></div><Tag tone="neutral">Demo history</Tag></div><div className="chart-area"><ResponsiveContainer width="100%" height="100%"><LineChart data={active} margin={{top:10,right:15,bottom:0,left:0}}><CartesianGrid strokeDasharray="3 6" vertical={false} stroke="#e9ede6"/><XAxis dataKey="m" axisLine={false} tickLine={false} tick={{fill:'#849087',fontSize:12}}/><YAxis axisLine={false} tickLine={false} tick={{fill:'#849087',fontSize:11}} domain={['dataMin - 500','dataMax + 300']}/><Tooltip formatter={(v:any)=>[`₹${v}/qtl`,'Sample price']}/><Line type="monotone" dataKey="p" stroke="#3d764c" strokeWidth={3} dot={{r:3,fill:'#fff',stroke:'#3d764c',strokeWidth:2}} activeDot={{r:5}}/></LineChart></ResponsiveContainer></div><div className="chart-foot"><span><i className="legend-dot"/> Sample modal price</span><span>Prices shown for demonstration only</span></div></section><div className="info-callout market-info"><CircleHelp size={16}/><span>Prices vary by market, quality and date. Check the official APMC or Agmarknet listing before making a sale decision.</span></div></>}
function Weather({tr}:any){return <><PageHead eyebrow="LOCAL CONDITIONS" title={tr.weather} subtitle="A planning view for Baramati, Pune district." action={<button className="btn btn-outline" onClick={()=>{}}>⌖ &nbsp; Baramati, Pune <ChevronDown size={14}/></button>}/><DemoNote tr={tr}/><div className="weather-hero"><div className="weather-now"><div><span className="eyebrow">TODAY · SAMPLE CONDITIONS</span><h2>Partly cloudy</h2><p>Tuesday, 18 June · Baramati</p></div><div className="weather-temp"><span>🌤️</span><b>29°</b><small>Feels like 32°</small></div></div><div className="weather-stats"><div><Droplets size={16}/><span>Humidity</span><b>68%</b></div><div><CloudSun size={16}/><span>Rainfall</span><b>8 mm</b></div><div><Activity size={16}/><span>Wind</span><b>12 km/h</b></div></div></div><section className="panel forecast-panel"><div className="chart-heading"><div><span className="eyebrow">NEXT 7 DAYS</span><h2>Plan around the weather</h2></div><Tag tone="amber">Sample forecast</Tag></div><div className="forecast-row">{weekData.map((w,i)=><div className={`forecast-day ${i===0?'today':''}`} key={w.day}><small>{i===0?'Today':w.day}</small><span>{['🌤️','⛅','🌦️','🌧️','☀️','🌦️','⛅'][i]}</span><b>{w.temp}°</b><small className="rain-amount"><Droplets size={12}/>{w.rain} mm</small></div>)}</div></section><div className="alert-card"><span>⚠️</span><div><b>Monsoon timing can vary</b><p>This is sample information. Do not use it as a live weather alert or delay urgent farm decisions because of this page.</p></div><Tag tone="amber">Sample alert</Tag></div></>}
function Expert({tr,cases,setCases}:any){const [category,setCategory]=useState('Crop choice');const [message,setMessage]=useState('');const [sent,setSent]=useState(false);const send=(e:any)=>{e.preventDefault();if(!message.trim())return;const item={id:`PN-${Math.floor(1000+Math.random()*8999)}`,category,message,status:'Pending',date:new Date().toLocaleDateString('en-IN',{day:'numeric',month:'short'})};setCases((prev:any[])=>[item,...prev]);setMessage('');setSent(true);setTimeout(()=>setSent(false),3000)};return <><PageHead eyebrow="LOCAL SUPPORT" title={tr.expert} subtitle="Ask a question and our sample expert desk will help you think it through."/><div className="expert-banner"><div className="expert-illustration">👩🏽‍🌾</div><div><span className="eyebrow">A REAL PERSON CAN HELP</span><h2>You're not alone in this decision.</h2><p>Share what you're unsure about. In a real service, a local expert would follow up.</p></div><div className="expert-live"><i/> Desk open<br/><small>Demo response only</small></div></div><div className="expert-grid"><form className="panel question-form" onSubmit={send}><div className="panel-heading"><div><h2>Send your question</h2><p>Include a little context to help us understand.</p></div><MessageCircle size={20} className="muted-icon"/></div><label>What is your question about?<select value={category} onChange={e=>setCategory(e.target.value)}>{['Crop choice','Soil & water','Weather','Market prices','Pest or disease','Other'].map(x=><option key={x}>{x}</option>)}</select></label><label>Your question<textarea value={message} onChange={e=>setMessage(e.target.value)} rows={5} maxLength={500} placeholder="For example: I have 2 acres of rainfed land. Which crops should I consider this Kharif?" required/></label><div className="question-bottom"><small>{message.length}/500 characters · Stored on this device</small><button className="btn btn-primary" type="submit"><MessageCircle size={15}/>{sent?'Submitted':tr.submit}</button></div></form><div className="panel cases-panel"><div className="panel-heading"><div><h2>{tr.cases}</h2><p>Follow the questions you have sent.</p></div><Tag tone="neutral">{cases.length} total</Tag></div>{cases.length?cases.map((c:any)=><div className="case-item" key={c.id}><div className={`case-status ${c.status==='Answered'?'answered':''}`}>{c.status==='Answered'?<Check size={14}/>:<Activity size={14}/>}</div><div className="case-info"><div><b>{c.category}</b><Tag tone={c.status==='Answered'?'green':c.status==='In review'?'amber':'neutral'}>{c.status}</Tag></div><p>{c.message}</p><small>{c.id} · {c.date}</small>{c.answer&&<div className="answer-box"><b>Sample expert reply</b><p>{c.answer}</p></div>}</div></div>):<div className="empty-state">Your submitted questions will appear here.</div>}</div></div><div className="info-callout"><ShieldCheck size={16}/><span>This is a demonstration. Questions are not sent to an actual expert in this prototype.</span></div></>}
function History({tr,advisories,navigate}:any){const ids=advisories.slice(0,5);return <><PageHead eyebrow="SAVED ON THIS DEVICE" title={tr.history} subtitle="Return to a previous demonstration crop shortlist."/><DemoNote tr={tr}/>{ids.length?ids.map((id:string,i:number)=>{const c=crops.find(x=>x.id===id)||crops[0];return <div className="history-item" key={`${id}-${i}`}><CropArt crop={c}/><div><span className="eyebrow">{i===0?'MOST RECENT':'PREVIOUS DEMO'} · {c.season.toUpperCase()}</span><h3>{c.local} <small>and other crop options</small></h3><p>Illustrative advisory · {c.fit}% fit · Saved in this browser</p></div><button className="btn btn-outline" onClick={()=>navigate('/farmer/advisory/results')}>Open shortlist <ArrowRight size={15}/></button></div>}):<div className="empty-state">Your saved advice will appear here after you explore crop recommendations.</div>}</>}
function SettingsPage({tr,lang,setLang,profile}:any){const [voice,setVoice]=useState(true);const [large,setLarge]=useState(false);return <><PageHead eyebrow="YOUR PREFERENCES" title={tr.settings} subtitle="Make PikNirnay feel right for you."/><div className="settings-grid"><section className="panel settings-panel"><div className="panel-heading"><div><h2>Language</h2><p>Choose the language used across the app.</p></div><Globe2 size={19} className="muted-icon"/></div>{[['mr','मराठी'],['hi','हिंदी'],['en','English']].map(([id,name])=><button className={`language-row ${lang===id?'selected':''}`} key={id} onClick={()=>setLang(id)}><span>{name}</span>{lang===id?<span className="language-check"><Check size={14}/></span>:<ChevronRight size={16}/>}</button>)}</section><section className="panel settings-panel"><div className="panel-heading"><div><h2>Accessibility</h2><p>Adjust the app for easier reading.</p></div><Heart size={18} className="muted-icon"/></div><Toggle title="Voice prompts" desc="Hear simple spoken guidance" on={voice} setOn={setVoice}/><Toggle title="Larger text" desc="Increase text size across the app" on={large} setOn={setLarge}/></section><section className="panel settings-panel profile-summary"><div className="panel-heading"><div><h2>Your farm details</h2><p>Saved only in this browser.</p></div><Link to="/farmer/farm-profile" className="text-link">Edit <ArrowRight size={14}/></Link></div><Metric label="Location" value={`${profile.village}, ${profile.district}`}/><Metric label="Land" value={`${profile.area} ${profile.unit}`}/><Metric label="Soil & water" value={`${profile.soil} · ${profile.water}`}/></section></div></>}
function Toggle({title,desc,on,setOn}:any){return <div className="toggle-row"><div><b>{title}</b><small>{desc}</small></div><button role="switch" aria-checked={on} onClick={()=>setOn(!on)} className={`toggle ${on?'on':''}`}><i/></button></div>}
function ExpertDesk({tr,cases,setCases}:any){const [filter,setFilter]=useState('All cases');const [active,setActive]=useState<any>(null);const [reply,setReply]=useState('');const filtered=cases.filter((c:any)=>filter==='All cases'||c.status===filter);return <><PageHead eyebrow="EXPERT WORKSPACE · SAMPLE" title="Expert desk" subtitle="A demonstration queue for farmer questions." action={<Tag tone="amber">SAMPLE CASES</Tag>}/><div className="admin-stats"><StatCard icon={<MessageCircle/>} label="Assigned cases" value="12" note="Sample queue"/><StatCard icon={<Activity/>} label="Pending" value="5" note="Needs a response" tone="amber"/><StatCard icon={<Check/>} label="Resolved" value="27" note="This month" tone="green"/><StatCard icon={<Users/>} label="Farmers helped" value="34" note="Illustrative totals" tone="blue"/></div><section className="panel table-panel"><div className="table-toolbar"><div><h2>Farmer questions</h2><p>Open a case to add notes or update its status.</p></div><select value={filter} onChange={e=>setFilter(e.target.value)}><option>All cases</option><option>Pending</option><option>In review</option><option>Answered</option><option>Resolved</option></select></div><div className="table-wrap"><table><thead><tr><th>CASE</th><th>FARMER</th><th>CATEGORY</th><th>QUESTION</th><th>STATUS</th><th>RECEIVED</th><th/></tr></thead><tbody>{filtered.map((c:any,i:number)=><tr key={c.id}><td className="id-cell">{c.id}</td><td><div className="table-person"><span>{['स','म','अ','प'][i%4]}</span> Demo Farmer</div></td><td>{c.category}</td><td className="question-cell">{c.message}</td><td><Tag tone={c.status==='Answered'||c.status==='Resolved'?'green':c.status==='In review'?'amber':'neutral'}>{c.status}</Tag></td><td>{c.date}</td><td><button className="row-action" onClick={()=>{setActive(c);setReply('')}}>Review <ChevronRight size={14}/></button></td></tr>)}</tbody></table></div>{!filtered.length&&<div className="empty-state">No cases in this view.</div>}</section>{active&&<div className="modal-backdrop" onClick={()=>setActive(null)}><section className="modal panel" onClick={e=>e.stopPropagation()}><button className="modal-close icon-btn" onClick={()=>setActive(null)}><X size={18}/></button><span className="eyebrow">CASE {active.id}</span><h2>{active.category}</h2><p className="modal-question">{active.message}</p><label>Expert notes<textarea rows={3} placeholder="Add internal note for the case..."/></label><label>Response to farmer<textarea rows={4} placeholder="Write a simple, practical response..." value={reply} onChange={e=>setReply(e.target.value)}/></label><div className="modal-actions"><select defaultValue={active.status} onChange={e=>{const status=e.target.value;setActive({...active,status});setCases((prev:any[])=>prev.map(x=>x.id===active.id?{...x,status}:x))}}><option>Pending</option><option>In review</option><option>Answered</option><option>Resolved</option></select><button className="btn btn-primary" onClick={()=>{if(reply.trim()){setCases((prev:any[])=>prev.map(x=>x.id===active.id?{...x,status:'Answered',answer:reply}:x));setActive(null)}}}>Save response <Check size={15}/></button></div><small className="field-help">Demonstration only. This does not send a real message.</small></section></div>}</>}
function StatCard({icon,label,value,note,tone='green'}:any){return <div className="admin-stat"><span className={`admin-stat-icon ${tone}`}>{icon}</span><small>{label}</small><b>{value}</b><span className="stat-note">{note}</span></div>}
function Admin({tr,cases}:any){
 const path=useLocation().pathname; const tab=path.split('/')[2]||'dashboard';
 const names:any={dashboard:'Overview',crops:'Crop library','data-sources':'Data sources','data-freshness':'Data freshness',users:'Farmers','expert-cases':'Expert cases',models:'Model registry','audit-logs':'Activity log'};
 const [query,setQuery]=useState(''); const [season,setSeason]=useState('All seasons'); const [detail,setDetail]=useState<any>(null);
 const nav=[['dashboard','Overview'],['users','Farmers'],['crops','Crop library'],['data-sources','Data sources'],['data-freshness','Data freshness'],['models','Model registry'],['expert-cases','Expert cases'],['audit-logs','Activity log']];
 let headers:string[]=[]; let rows:any[][]=[]; let title=''; let desc='';
 if(tab==='crops'){headers=['CROP','SEASON','DURATION','SAMPLE COST','LOSS RISK','STATUS'];title='Configured crop examples';desc='Editable demonstration catalogue; not agronomist-validated.';rows=crops.filter(c=>(season==='All seasons'||c.season===season)&&(c.name.toLowerCase().includes(query.toLowerCase())||c.local.includes(query))).map(c=>[<b>{c.local}<small className="sub-cell">{c.name}</small></b>,c.season,`${c.duration} days`,`₹${fmt(c.cost)}`,`${c.loss}%`,<Tag tone="amber">Illustrative</Tag>]);}
 if(tab==='users'){headers=['FARMER','LOCATION','LAND','LANGUAGE','LAST ACTIVE','STATUS'];title='Demonstration farmers';desc='Sample farmer profiles for this prototype.';rows=['Pune · 2 acres','Nashik · 1.5 acres','Solapur · 3 acres','Nagpur · 1 acre','Latur · 2.5 acres'].map((x,i)=>[<b>Demo Farmer {String(i+1).padStart(2,'0')}</b>,x,`${[2,1.5,3,1,2.5][i]} acres`,['Marathi','Hindi','Marathi','English','Marathi'][i],'Today',<Tag tone="green">Active demo</Tag>]);}
 if(tab==='expert-cases'){headers=['CASE','CATEGORY','QUESTION','STATUS','DATE'];title='Expert case queue';desc='Sample case summaries from the demonstration.';rows=cases.map((c:any)=>[<b>{c.id}</b>,c.category,c.message,<Tag tone={c.status==='Answered'?'green':'amber'}>{c.status}</Tag>,c.date]);}
 if(tab==='data-sources'){headers=['SOURCE','DATA TYPE','COVERAGE','LAST CHECK','STATUS'];title='Source register';desc='Planned inputs for a future validated pilot.';rows=['IMD · Rainfall','Agmarknet · Prices','Maharashtra agriculture · Crop rules','Soil Health Card · Soil data'].map((x,i)=>[<b>{x}</b>,['Weather','Market','Agronomy','Soil'][i],['India','Maharashtra','Maharashtra','Farmer provided'][i],'Not connected',<Tag tone="neutral">Planned</Tag>]);}
 if(tab==='models'){headers=['COMPONENT','VERSION','STATUS','INPUTS','LAST REVIEW'];title='Demonstration components';desc='A transparent record of what is active in this prototype.';rows=['Crop suitability scorer','Return range examples','Risk profile mapping','Explanation templates'].map((x,i)=>[<b>{x}</b>,`0.${i+1}.0`,<Tag tone="amber">Illustrative</Tag>,['Soil, water, season','Static sample values','Risk profiles','Rule-based text'][i],'Not validated']);}
 if(tab==='audit-logs'){headers=['TIME','ACTOR','EVENT','DETAIL','SOURCE'];title='Recent activity';desc='Sample administrative events. No personal data is included.';rows=['Demo Farmer opened advisory','Admin reviewed crop catalogue','Expert responded to sample case','Demo Farmer updated farm profile','System loaded demo season','Admin opened data freshness'].filter(x=>x.toLowerCase().includes(query.toLowerCase())).map((x,i)=>[`${10-i}:2${i} AM`,i%2?'Admin user':'Demo user',x.split(' ').slice(1,3).join(' '),x,'Demo browser']);}
 return <div className="admin-layout"><aside className="admin-nav"><div className="admin-brand"><div className="admin-mark"><Gauge size={17}/></div><div><b>Control room</b><small>PikNirnay demo</small></div></div>{nav.map(([id,name],i)=><NavLink key={id} to={`/admin/${id}`} className={({isActive})=>`admin-nav-link ${isActive?'current':''}`}><span>{['◫','♙','✿','⌁','◷','◉','☷','≡'][i]}</span>{name}<ChevronRight size={14}/></NavLink>)}<div className="admin-nav-note"><ShieldCheck size={15}/><span>Demo workspace<br/><b>Sample data only</b></span></div></aside>
 <div className="admin-content"><div className="admin-pagehead"><div><span className="eyebrow">ADMINISTRATION / {names[tab]||'Overview'}</span><h1>{names[tab]||'Overview'}</h1><p>Monitor the PikNirnay demonstration workspace.</p></div><div className="admin-actions"><Tag tone="amber">DEMO ENVIRONMENT</Tag><div className="admin-user">AD</div></div></div>
 {tab==='dashboard'?<AdminOverview cases={cases}/>:tab==='data-freshness'?<DataTable title="Data freshness" desc="All values are illustrative; no live integrations are connected." headers={['DATA','STATUS','DETAIL','NEXT CHECK']} rows={['Crop examples','Market prices','Weather forecast','Soil conditions'].map(x=>[<b>{x}</b>,<Tag tone="amber">Illustrative</Tag>,'Sample records only','Not scheduled'])} onRow={(i:number)=>setDetail({name:['Crop examples','Market prices','Weather forecast','Soil conditions'][i]})}/>:<><div className="admin-toolbar">{['crops','audit-logs'].includes(tab)&&<div className="search-box"><Search size={15}/><input placeholder="Search records..." value={query} onChange={e=>setQuery(e.target.value)}/></div>}{tab==='crops'&&<select value={season} onChange={e=>setSeason(e.target.value)}><option>All seasons</option><option>Kharif</option><option>Rabi</option></select>}{tab==='crops'&&<button className="btn btn-primary" onClick={()=>setDetail({name:'New crop record'})}><Plus size={15}/>Add crop</button>}</div><DataTable title={title} desc={desc} headers={headers} rows={rows} onRow={(i:number)=>setDetail({name:tab==='crops'?filteredCropName(i,season,query):title,record:rows[i]})}/></>}
 {detail&&<div className="modal-backdrop" onClick={()=>setDetail(null)}><section className="modal panel" onClick={e=>e.stopPropagation()}><button className="modal-close icon-btn" onClick={()=>setDetail(null)}><X size={18}/></button><span className="eyebrow">DEMONSTRATION DETAIL</span><h2>{detail.name||'Record details'}</h2><p>This record is illustrative and has not been validated for field use. No live source is connected.</p><button className="btn btn-outline" onClick={()=>setDetail(null)}>Close</button></section></div>}</div></div>
}
function filteredCropName(i:number,season:string,query:string){return crops.filter(c=>(season==='All seasons'||c.season===season)&&(c.name.toLowerCase().includes(query.toLowerCase())||c.local.includes(query)))[i]?.name||'Crop record'}
function DataTable({title,desc,headers,rows,onRow}:any){return <section className="panel table-panel"><div className="table-toolbar"><div><h2>{title}</h2><p>{desc}</p></div><span className="record-count">{rows.length} records</span></div><div className="table-wrap"><table><thead><tr>{headers.map((h:string)=><th key={h}>{h}</th>)}<th/></tr></thead><tbody>{rows.map((r:any[],i:number)=><tr key={i} onClick={()=>onRow(i)}>{r.map((v:any,j:number)=><td key={j}>{v}</td>)}<td><button className="icon-btn table-more" onClick={e=>{e.stopPropagation();onRow(i)}}><ChevronRight size={16}/></button></td></tr>)}</tbody></table></div>{!rows.length&&<div className="empty-state">No matching records.</div>}</section>}
function AdminOverview({cases}:any){const [period,setPeriod]=useState('Last 30 days');const chart=[{name:'Wk 1',soy:22,cot:12,tur:15},{name:'Wk 2',soy:31,cot:18,tur:19},{name:'Wk 3',soy:27,cot:15,tur:23},{name:'Wk 4',soy:40,cot:22,tur:28},{name:'Wk 5',soy:36,cot:20,tur:25},{name:'Wk 6',soy:48,cot:28,tur:33}];return <><div className="admin-stats"><StatCard icon={<Users/>} label="Demo farmer profiles" value="248" note="+18 this month"/><StatCard icon={<Sprout/>} label="Advisory requests" value="1,286" note="Illustrative count" tone="blue"/><StatCard icon={<MessageCircle/>} label="Expert cases" value={cases.length+34} note={`${cases.filter((c:any)=>c.status==='Pending').length+5} awaiting response`} tone="amber"/><StatCard icon={<ShieldCheck/>} label="Data freshness" value="Sample" note="No live sources" tone="green"/></div><div className="admin-overview-grid"><section className="panel admin-chart-panel"><div className="chart-heading"><div><span className="eyebrow">ADVISORY ACTIVITY</span><h2>Requests over time</h2></div><select value={period} onChange={e=>setPeriod(e.target.value)}><option>Last 30 days</option><option>Last 7 days</option><option>This season</option></select></div><div className="admin-chart"><ResponsiveContainer width="100%" height="100%"><BarChart data={chart} barGap={4}><CartesianGrid strokeDasharray="3 6" vertical={false} stroke="#e9ede6"/><XAxis dataKey="name" axisLine={false} tickLine={false} tick={{fill:'#849087',fontSize:11}}/><YAxis axisLine={false} tickLine={false} tick={{fill:'#849087',fontSize:11}}/><Tooltip/><Bar dataKey="soy" name="Soybean" fill="#4f8056" radius={[4,4,0,0]}/><Bar dataKey="cot" name="Cotton" fill="#b4c9a4" radius={[4,4,0,0]}/><Bar dataKey="tur" name="Tur" fill="#e0bf7c" radius={[4,4,0,0]}/></BarChart></ResponsiveContainer></div><div className="chart-legend"><span><i style={{background:'#4f8056'}}/>Soybean</span><span><i style={{background:'#b4c9a4'}}/>Cotton</span><span><i style={{background:'#e0bf7c'}}/>Tur</span></div></section><section className="panel distribution-panel"><div className="chart-heading"><div><span className="eyebrow">FARMER INTEREST</span><h2>Top crops</h2></div><Tag tone="neutral">Sample</Tag></div>{[['Soybean',34],['Cotton',24],['Tur',19],['Chana',13],['Other',10]].map(([n,v]:any,i)=><div className="dist-row" key={n}><div><span>{n}</span><b>{v}%</b></div><div className="dist-track"><i style={{width:`${v*2}%`,background:['#4f8056','#85a477','#b4c9a4','#d5c18b','#d9ddd4'][i]}}/></div></div>)}<Link className="card-link" to="/admin/crops">Explore crop library <ArrowRight size={14}/></Link></section></div><div className="admin-bottom-grid"><section className="panel admin-data"><div className="panel-heading"><div><h2>Data sources</h2><p>Connections planned for the future pilot</p></div><Link className="text-link" to="/admin/data-sources">View all <ArrowRight size={13}/></Link></div>{[['IMD · Weather','Planned'],['Agmarknet · Prices','Planned'],['Crop rules','Illustrative']].map(([n,s])=><div className="data-row" key={n}><span className="source-dot"/><b>{n}</b><Tag tone="amber">{s}</Tag></div>)}</section><section className="panel admin-data"><div className="panel-heading"><div><h2>Recent activity</h2><p>Sample events in this workspace</p></div><Link className="text-link" to="/admin/audit-logs">View log <ArrowRight size={13}/></Link></div>{[['10:24','Advisory request viewed'],['09:58','Crop list opened'],['09:42','Expert case updated']].map(([time,x])=><div className="activity-row" key={x}><span>{time}</span><p>{x}</p><i/></div>)}</section></div></>}
function PublicHeader({lang,setLang}:any){return <header className="public-header"><Link className="brand" to="/"><span className="brand-mark">🌱</span><span><b>PikNirnay</b><small>पीक निर्णय</small></span></Link><nav><Link to="/how-it-works">How it works</Link><Link to="/language">Languages</Link><a href="#principles">Our promise</a></nav><div className="public-actions"><select value={lang} onChange={e=>setLang(e.target.value)}><option value="mr">मराठी</option><option value="hi">हिंदी</option><option value="en">English</option></select><Link to="/demo-access" className="btn btn-primary">Try the demo <ArrowRight size={15}/></Link></div></header>}
function Landing({lang,setLang}:any){return <div className="public-page"><PublicHeader lang={lang} setLang={setLang}/><section className="hero-public"><div className="hero-public-copy"><div className="hero-badge"><span>✳</span> THE SEASON DECISION COMPANION</div><h1>Make this season’s<br/><em>big decision</em><br/>with confidence.</h1><p>Know what could grow well, what it might cost, and where the risks lie — in a language that feels like yours.</p><div className="hero-buttons"><Link to="/demo-access" className="btn btn-primary btn-large">Explore crop advice <ArrowRight size={17}/></Link><Link to="/how-it-works" className="btn btn-plain">See how it works <ChevronRight size={16}/></Link></div><div className="hero-proof"><span className="proof-avatars"><i>👩🏽‍🌾</i><i>👨🏽‍🌾</i><i>🧑🏽‍🌾</i></span><span>Built around the decisions<br/>farmers make every season</span></div></div><div className="hero-visual"><div className="hero-photo"/><div className="sunburst"/><div className="field-illustration"><div className="field-hill field-back"/><div className="field-hill field-mid"/><div className="field-hill field-front"/><span className="hero-plant plant-a">🌿</span><span className="hero-plant plant-b">🌾</span><span className="hero-plant plant-c">🌱</span></div><div className="floating-note note-one"><span className="note-leaf">🌱</span><div><small>YOUR TOP MATCH</small><b>Soybean <Tag tone="green">91%</Tag></b></div></div><div className="floating-note note-two"><div className="note-icon">₹</div><div><small>ESTIMATED NET RETURN</small><b>₹26k – ₹44k <span>/ acre</span></b></div></div><div className="handwritten">A little more clarity<br/>for the road ahead <span>↗</span></div><div className="visual-stamp">FOR EVERY<br/>GROWING SEASON</div></div><div className="hero-leaf leaf-one">✳</div><div className="hero-leaf leaf-two">✿</div></section><section className="promise-strip" id="principles"><div><span className="promise-symbol">◌</span><b>Ranges, never promises</b><small>Honest estimates with risk shown</small></div><div><span className="promise-symbol">⌁</span><b>Advice you can question</b><small>Clear reasons behind every crop</small></div><div><span className="promise-symbol">♡</span><b>A human when you need one</b><small>Expert support is part of the plan</small></div><div><span className="promise-symbol">◉</span><b>Made for your language</b><small>Marathi · Hindi · English</small></div></section><section className="public-intro"><span className="eyebrow">A DIFFERENT KIND OF CROP ADVICE</span><h2>More than “what can grow.”</h2><p>Choosing a crop is choosing how your family invests its season. PikNirnay brings soil, water, timing and money into one simple view.</p><div className="intro-cards"><div><span>01</span><Sprout size={21}/><h3>Find what fits</h3><p>Start with the soil and water your farm really has.</p></div><div><span>02</span><TrendingUp size={21}/><h3>See the trade-offs</h3><p>Compare estimated costs, returns and possible losses.</p></div><div><span>03</span><MessageCircle size={21}/><h3>Ask a person</h3><p>Get an expert involved when the answer is uncertain.</p></div></div></section><section className="public-cta"><span className="eyebrow">YOUR NEXT SEASON STARTS HERE</span><h2>Let’s make the decision a little clearer.</h2><p>Take a few minutes to explore your options. No account needed.</p><Link to="/demo-access" className="btn btn-light btn-large">Start the free demo <ArrowRight size={17}/></Link></section><footer className="public-footer"><Link className="brand" to="/"><span className="brand-mark">🌱</span><span><b>PikNirnay</b><small>Right crop. Right time. Right risk.</small></span></Link><span>Illustrative prototype · not validated for farming decisions</span><Link to="/how-it-works">About the project</Link></footer></div>}
function LanguagePage({lang,setLang}:any){const nav=useNavigate();return <div className="public-page"><PublicHeader lang={lang} setLang={setLang}/><div className="public-simple"><span className="eyebrow">MADE TO FEEL FAMILIAR</span><h1>Choose your language</h1><p>Change this anytime in your settings.</p><div className="language-cards">{[['mr','मराठी','तुमची भाषा, तुमचा निर्णय'],['hi','हिंदी','आपकी भाषा, आपका फ़ैसला'],['en','English','Your language, your decision']].map(([id,name,desc])=><button key={id} className={`language-choice ${lang===id?'selected':''}`} onClick={()=>{setLang(id);nav('/welcome')}}><span className="language-symbol">{id==='mr'?'अ':id==='hi'?'अ':'A'}</span><b>{name}</b><small>{desc}</small><ChevronRight size={18}/></button>)}</div></div></div>}
function Welcome({lang,setLang}:any){return <div className="public-page"><PublicHeader lang={lang} setLang={setLang}/><div className="welcome-simple"><div className="welcome-orb">🌱</div><span className="eyebrow">WELCOME TO PIKNIRNAY</span><h1>A thoughtful start<br/>to a better season.</h1><p>No sign-up needed. We'll ask a few simple questions about your farm and show a sample crop shortlist.</p><Link to="/demo-access" className="btn btn-primary btn-large">Continue as a guest <ArrowRight size={17}/></Link><small>Any figures you see are illustrative demo data.</small></div></div>}
function PublicPage({title,lang,setLang}:any){return <div className="public-page"><PublicHeader lang={lang} setLang={setLang}/><div className="public-simple how-page"><span className="eyebrow">A CLEARER SEASON DECISION</span><h1>{title}</h1><p>PikNirnay brings your farm’s soil, water, season and risk comfort into one easy-to-understand crop shortlist.</p><div className="how-steps">{[['01','Tell us about your farm','Share your location, land, soil and water access. Guest mode keeps everything on this device.'],['02','Choose your season and comfort with risk','Pick Kharif or Rabi and tell us whether you prefer cautious, balanced or ambitious options.'],['03','Explore a crop shortlist','See sample cost, return range, loss chance, sowing window and the reasons behind each option.'],['04','Compare or ask a question','Compare two crops side by side, or prepare a question for the expert desk.']].map(([num,h,p])=><div className="how-step" key={num}><span>{num}</span><div><h3>{h}</h3><p>{p}</p></div></div>)}</div><div className="info-callout"><ShieldCheck size={16}/><span>This website is a demonstration prototype. Its sample figures are not a validated agricultural recommendation.</span></div><Link to="/demo-access" className="btn btn-primary btn-large">Try the demo <ArrowRight size={16}/></Link></div></div>}


export default App;
